fn first_word(s: Str) -> Str {
  var i = 0;
  while i < s.len() {
    if str_slice(s, i, i + 1) == " " {
      return str_slice(s, 0, i);
    }
    i = i + 1;
  }
  return s;
}

fn file_extension(filename: Str) -> Str {
  var dot_pos = 0;
  var i = 0;
  while i < filename.len() {
    if str_slice(filename, i, i + 1) == "." {
      dot_pos = i;
    }
    i = i + 1;
  }
  if dot_pos == 0 { return ""; }
  return str_slice(filename, dot_pos + 1, filename.len());
}

fn main() -> Int {
  let ext = file_extension("document.pdf");
  return ext.len();
}
